export function PersonasPanel({ initialId }: Props) {
  const { personas, save, remove } = PersonaStore.usePersonas();
  const [id, setId] = useState(initialId ?? personas[0]?.id);
  return (
    <PersonaShell title="Personas" rail={<PersonaList personas={personas} activeId={id} onPick={setId} />}>
      <PersonaForm value={personas.find((p) => p.id === id)} onSave={save} onDelete={remove} />
    </PersonaShell>
  );
}

export function AgentsBoard({ agents, onOpen }: Props) {
  return (
    <PersonaShell title="Agents">
      <div className="board-grid">
        {agents.map((a) => <AgentTile key={a.id} agent={a} onOpen={onOpen} />)}
      </div>
    </PersonaShell>
  );
}

export function PersonaShell({ title, rail, children }: Props) {
  return (
    <div className="shell">
      <DemoHeading>{title}</DemoHeading>
      <div className="shell-cols">
        {rail && <aside className="shell-rail">{rail}</aside>}
        <main className="shell-main">{children}</main>
      </div>
    </div>
  );
}

export function PersonaList({ personas, activeId, onPick }: Props) {
  const [q, setQ] = useState("");
  const hits = personas.filter((p) => p.name.toLowerCase().includes(q.toLowerCase()));
  return (
    <div className="plist">
      <DemoField label="Search" value={q} onChange={setQ} />
      {hits.map((p) => <PersonaRow key={p.id} persona={p} active={p.id === activeId} onClick={() => onPick(p.id)} />)}
    </div>
  );
}

export function PersonaRow({ persona, active, onClick }: Props) {
  return (
    <button className={active ? "prow active" : "prow"} onClick={onClick}>
      <PersonaBadge name={persona.name} />
      <span className="prow-name">{persona.name}</span>
      <RoleTag role={persona.role} />
    </button>
  );
}

export function PersonaForm({ value, onSave, onDelete }: Props) {
  const [draft, setDraft] = useState(value);
  return (
    <form className="pform" onSubmit={() => onSave(draft)}>
      <DemoField label="Name" value={draft.name} onChange={(name) => setDraft({ ...draft, name })} />
      <DemoField label="Start prompt" value={draft.prompt} onChange={(prompt) => setDraft({ ...draft, prompt })} />
      <DemoButton variant="primary" type="submit">Save</DemoButton>
      {onDelete && <DemoButton variant="danger" onClick={() => onDelete(draft.id)}>Delete</DemoButton>}
    </form>
  );
}

export function AgentTile({ agent, onOpen }: Props) {
  return (
    <article className="atile" onClick={() => onOpen?.(agent.id)}>
      <PersonaBadge name={agent.persona.name} />
      <h3>{agent.persona.name}</h3>
      <RoleTag role={agent.persona.role} />
      <span className={`atile-dot ${agent.status}`} />
    </article>
  );
}

export function DemoButton({ variant = "ghost", ...rest }: Props) {
  return <button className={`btn btn-${variant}`} {...rest} />;
}

export function DemoField({ label, value, onChange, error }: Props) {
  return (
    <label className="field">
      <span className="field-label">{label}</span>
      <input value={value} onChange={(e) => onChange(e.target.value)} aria-invalid={!!error} />
      {error && <span className="field-error">{error}</span>}
    </label>
  );
}

const TONE = { planner: "violet", worker: "green", director: "blue" } as const;
export function RoleTag({ role, compact }: Props) {
  return <span className={`tag tag-${TONE[role]}`}>{compact ? "" : role}</span>;
}

export function PersonaBadge({ name, size = 28 }: Props) {
  const initials = name.split(/\s+/).map((w) => w[0]).slice(0, 2).join("");
  const hue = [...name].reduce((h, ch) => (h * 31 + ch.charCodeAt(0)) % 360, 0);
  return <span className="badge" style={{ width: size, height: size, background: `oklch(0.35 0.09 ${hue})` }}>{initials}</span>;
}

export function DemoHeading({ children, hint }: Props) {
  return (
    <h2 className="heading">
      {children}
      {hint && <span className="heading-hint">{hint}</span>}
    </h2>
  );
}

export const PersonaStore = {
  usePersonas() {
    const [personas, setPersonas] = useState<Persona[]>([]);
    useEffect(() => PersonaStore.subscribe(setPersonas), []);
    return { personas, save: PersonaStore.save, remove: PersonaStore.remove };
  },
  save: (p: Persona) => bridge("persona set", p),
  remove: (id: string) => bridge("persona remove", { id }),
};
